-- Normalise the middle tier's copy so the three cards read as one ladder.
UPDATE "packages" SET "name" = 'Standart Paket', "description" = 'En çok tercih edilen paket. Kaynak dosyalar ve revizyon hakkı dahil.' WHERE "tier" = 'STANDARD';
